with lines as (select id, plan, effective_from, tier_value from price_tiers lateral view outer explode(tier_prices) t as tier_value), enriched as (select *, max(tier_value) over w_ordered as plan_max_tier_value, min(tier_value) over w_ordered as plan_min_tier_value, dense_rank() over w_running as tier_value_dense_rank, avg(tier_value) over w_ordered as plan_avg_tier_value from lines window w_ordered as (partition by plan), w_running as (partition by plan order by tier_value desc nulls last)), metrics as (select *, cume_dist() over (order by tier_value desc nulls first) as tier_value_cume_dist, avg(plan_min_tier_value) over (partition by plan) as plan_avg_plan_min_tier_value from enriched), valid as (select *, ceil(tier_value_cume_dist) as tier_value_cume_dist_whole, tier_value_dense_rank / nullif(plan_avg_tier_value, 0) as tier_value_dense_rank_per_plan_avg_tier_value from metrics where effective_from > date '2024-07-06'), with_windows as (select *, avg(tier_value_cume_dist_whole) over w_ordered as plan_avg_tier_value_cume_dist_whole, avg(plan_min_tier_value) over w_ordered as plan_avg_plan_min_tier_value_2 from valid window w_ordered as (partition by plan)) select case when plan_min_tier_value >= 79 then 'HIGH' else 'LOW' end as plan_min_tier_value_tier, plan, approx_percentile(plan_avg_tier_value_cume_dist_whole, array(0.25, 0.5, 0.75)) as plan_avg_tier_value_cume_dist_whole_quartiles, max(tier_value_cume_dist_whole) as max_tier_value_cume_dist_whole, sort_array(collect_set(plan)) as plan_list, sort_array(collect_set(plan)) as plan_list_2, approx_percentile(plan_avg_plan_min_tier_value, array(0.25, 0.5, 0.75)) as plan_avg_plan_min_tier_value_quartiles from with_windows group by cube (case when plan_min_tier_value >= 79 then 'HIGH' else 'LOW' end, plan);
